      const records=safe(envelope.records?.requirementCompilationChallengeReviews),others=Object.entries(envelope.records||{}).filter(([collection,list])=>collection!=='requirementCompilationChallengeReviews'&&safe(list).length),expectedTempKeys=new Set(expectedTargets.map(target=>`challenge:${target.targetHash}`)),actualTempKeys=records.map(record=>String(record.tempKey||''));
